text:
{
  "requirements": [
    {
      "id": "r1",
      "label": "Sole Contact Person",
      "rfpQuote": "Bidder’s sole contact person during the RFP process. Include name, title, address, email, and phone number.",
      "section": "§0"
    },
    {
      "id": "r2",
      "label": "Authorized Contract Signer",
      "rfpQuote": "Person authorized to receive and sign a resulting contract. Include name, title, address, email, phone number",
      "section": "§0"
    },
    {
      "id": "r3",
      "label": "Company Background Information",
      "rfpQuote": "Legal business name and address. Include business entity designation, e.g., sole proprietor, Inc., LLC, or LLP.",
      "section": "§0"
    },
    {
      "id": "r4",
      "label": "Company History and Growth",
      "rfpQuote": "Discuss your company’s history. Has growth been organic, through mergers and acquisitions, or both?",
      "section": "§0"
    },
    {
      "id": "r5",
      "label": "Gross Annual Sales Scaling",
      "rfpQuote": "State your gross annual sales for each of the last 5 years.",
      "section": "§0"
    },
    {
      "id": "r6",
      "label": "Partnerships and Strategic Relationships",
      "rfpQuote": "Describe partnerships and strategic relationships you think will bring significant value to the State.",
      "section": "§0"
    },
    {
      "id": "r7",
      "label": "Primary Place of Business",
      "rfpQuote": "State the physical address of the place of business that would have primary responsibility for this account",
      "section": "§0"
    },
    {
      "id": "r8",
      "label": "Relevant Prior Experiences",
      "rfpQuote": "Describe at least 3 relevant experiences from the last 5 years supporting your ability to successfully manage",
      "section": "§0"
    },
    {
      "id": "r9",
      "label": "FTA Clauses Agreement",
      "rfpQuote": "Signed Agreement with the Federal Transit Administration (FDA) Clauses (Schedule E).",
      "section": "§1"
    },
    {
      "id": "r10",
      "label": "Altoona Test Bus Report",
      "rfpQuote": "Full Altoona Test Buse Report.",
      "section": "§1"
    },
    {
      "id": "r11",
      "label": "Motor Vehicle Dealer License",
      "rfpQuote": "Current Valid Motor Vehicle Dealer License",
      "section": "§1"
    },
    {
      "id": "r12",
      "label": "Affidavit for Driver Delivery",
      "rfpQuote": "Completed Affidavit for Driver Delivery (Schedule F).",
      "section": "§1"
    },
    {
      "id": "r13",
      "label": "Schedule D Specification Details",
      "rfpQuote": "all cells in “Product Detail or Pre-Approved Alternate” column must be completed by bidder for each item.",
      "section": "§2"
    },
    {
      "id": "r14",
      "label": "Permanent Decal or Metal Plate",
      "rfpQuote": "must be imprinted on a permanent decal(s) or stamped on a metal plate(s) and affixed in the driver's area",
      "section": "§2"
    },
    {
      "id": "r15",
      "label": "Final Inspection and Corrections",
      "rfpQuote": "The Contractor must be capable of handling final inspection and corrections required by the State prior to acceptance",
      "section": "§2"
    },
    {
      "id": "r16",
      "label": "Warranty Terms and Process",
      "rfpQuote": "Describe any warranties included in the bid and provide the length of the warranty.",
      "section": "§4"
    },
    {
      "id": "r17",
      "label": "Recall Procedures",
      "rfpQuote": "The Contractor must describe any recall procedures.",
      "section": "§5"
    },
    {
      "id": "r18",
      "label": "Quality Assurance Program",
      "rfpQuote": "Explain your Quality Assurance Program(s).",
      "section": "§6"
    },
    {
      "id": "r19",
      "label": "Special Incentives",
      "rfpQuote": "Explain any special incentives or services including, but not limited to, return policies, trade-in programs, quantity discounts, etc.",
      "section": "§7"
    },
    {
      "id": "r20",
      "label": "Contract Delivery Timeframe",
      "rfpQuote": "All Contract Activities must be delivered within 210 business days from receipt of order.",
      "section": "§8"
    },
    {
      "id": "r21",
      "label": "Training Services",
      "rfpQuote": "The Contractor must provide training when necessary, including but not limited to, aspects of ordering, shipping, billing, receiving,",
      "section": "§10"
    },
    {
      "id": "r22",
      "label": "Quarterly Reporting",
      "rfpQuote": "The Contractor must submit to the Program Manager quarterly reports which include agency name, vehicle(s) purchased, options, price,",
      "section": "§11"
    },
    {
      "id": "r23",
      "label": "Contractor Program Manager",
      "rfpQuote": "The Contractor must appoint a Service Manager or Product Representative specif i cally assigned to State of Michigan accounts",
      "section": "§13"
    },
    {
      "id": "r24",
      "label": "Key Personnel Appointment",
      "rfpQuote": "The Contractor must appoint one individual who will be directly responsible for the day-to-day operations of the Contract",
      "section": "§14"
    },
    {
      "id": "r25",
      "label": "Organizational Chart",
      "rfpQuote": "The Bidder must provide an overall organizational chart that details staff members, by name and title, and subcontractors",
      "section": "§16"
    },
    {
      "id": "r26",
      "label": "Customer Service Toll-Free Number",
      "rfpQuote": "The Contractor must specify its toll-free number for the State to contact the Contractor Program Manager",
      "section": "§17"
    },
    {
      "id": "r27",
      "label": "Subcontractor Disclosures",
      "rfpQuote": "If the Contractor intends to utilize subcontractors, the Contractor must disclose the following:",
      "section": "§18"
    },
    {
      "id": "r28",
      "label": "Facility Security Measures",
      "rfpQuote": "The Contractor must: (a) ensure the security of State facilities, (b) uses uniforms and ID badges, where required",
      "section": "§19"
    },
    {
      "id": "r29",
      "label": "Abnormal Order Verification Controls",
      "rfpQuote": "The Contractor must have internal controls approved by Central Procurement Services to verify abnormal orders",
      "section": "§22"
    },
    {
      "id": "r30",
      "label": "Pilot Model Production",
      "rfpQuote": "The Contractor should produce the pilot model as the first modified mini-vans ordered by the State for its transit",
      "section": "§24"
    },
    {
      "id": "r31",
      "label": "Travel Expenses for Inspection",
      "rfpQuote": "The Contractor should be responsible for transportation (air fare, rail fare, car rental, taxi, or mileage), lodging, parking expenses,",
      "section": "§26"
    },
    {
      "id": "r32",
      "label": "Invoice Content Requirements",
      "rfpQuote": "All invoices submitted to the State must include: (a) date; (b) purchase order; (c) quantity;",
      "section": "§29"
    },
    {
      "id": "r33",
      "label": "Environmental Product Identification",
      "rfpQuote": "The Contractor must identify any energy eficient, bio-based, or otherwise environmentally friendly f products used in the products.",
      "section": "§30"
    },
    {
      "id": "r34",
      "label": "Hazardous Chemical MSDS",
      "rfpQuote": "the Contractor must provide a Material Safety Data Sheet listing any hazardous chemicals as def i ned in 40 CFR",
      "section": "§31"
    },
    {
      "id": "r35",
      "label": "Mercury Content Disclosure",
      "rfpQuote": "The Contractor must explain if it intends to provide products containing mercury, the amount or concentration of mercury,",
      "section": "§32"
    },
    {
      "id": "r36",
      "label": "Brominated Flame Retardants Disclosure",
      "rfpQuote": "The Contractor must disclose whether the products contain BFRs. Contractor must describe how products that meet these requirements are",
      "section": "§33"
    },
    {
      "id": "r37",
      "label": "PFAS Disclosure and Confirmation",
      "rfpQuote": "The Contractor must conf i rm that the provided products do not intentionally contain PFAS.",
      "section": "§34"
    }
  ],
  "constraints": [
    {
      "id": "c1",
      "kind": "OTHER",
      "label": "Parts and Service Duration",
      "rfpQuote": "The Contractor must provide parts and service for a period of seven years after the vehicles have been placed",
      "section": "§2"
    },
    {
      "id": "c2",
      "kind": "DEADLINE",
      "label": "Replacement Parts Delivery Timeframe",
      "rfpQuote": "The Contractor must supply body replacement parts within five business days of a request by a transit agency",
      "section": "§2"
    },
    {
      "id": "c3",
      "kind": "OTHER",
      "label": "GVWR Ceiling Limit",
      "rfpQuote": "all vehicles delivered will not exceed the GVWR of chassis as bid",
      "section": "§2"
    },
    {
      "id": "c4",
      "kind": "DEADLINE",
      "label": "Delivery Completion Deadline",
      "rfpQuote": "All Contract Activities must be delivered within 210 business days from receipt of order.",
      "section": "§8"
    },
    {
      "id": "c5",
      "kind": "OTHER",
      "label": "Delivery Operating Hours",
      "rfpQuote": "Delivery must be made between the hours of 8:00 a.m. and 4:00 p.m., Monday through Friday only,",
      "section": "§9"
    },
    {
      "id": "c6",
      "kind": "SCOPE",
      "label": "Delivery Method Restriction",
      "rfpQuote": "The vehicle must be driven to the final destination",
      "section": "§9"
    },
    {
      "id": "c7",
      "kind": "DEADLINE",
      "label": "Program Manager Removal Notice",
      "rfpQuote": "notify the Contract Administrator at least 14 calendar days before removing or assigning a new Contractor Program Manager.",
      "section": "§13"
    },
    {
      "id": "c8",
      "kind": "DEADLINE",
      "label": "Key Personnel Inquiry Response Time",
      "rfpQuote": "respond to State inquiries within 24 hours.",
      "section": "§14"
    },
    {
      "id": "c9",
      "kind": "OTHER",
      "label": "Key Personnel Availability Hours",
      "rfpQuote": "Contractor’s Key Personnel must be available during the following times: 8:00 am – 5:00 pm.",
      "section": "§14"
    },
    {
      "id": "c10",
      "kind": "LEGAL",
      "label": "Consent for Key Personnel Removal",
      "rfpQuote": "The Contractor may not remove or assign Key Personnel without the prior consent of the State.",
      "section": "§14"
    },
    {
      "id": "c11",
      "kind": "DEADLINE",
      "label": "Non-Key Personnel Removal Notice",
      "rfpQuote": "notify the Contract Administrator at least 10-calendar days before removing or assigning non-key personnel.",
      "section": "§15"
    },
    {
      "id": "c12",
      "kind": "DEADLINE",
      "label": "Toll-Free Phone Hours",
      "rfpQuote": "available for calls during the hours of 8:00 am to 5:00 pm EST Monday through Friday,",
      "section": "§17"
    },
    {
      "id": "c13",
      "kind": "BUDGET",
      "label": "Fixed Price Period",
      "rfpQuote": "Pricing is firm for a 365-day period (“Pricing Period”).",
      "section": "§20"
    },
    {
      "id": "c14",
      "kind": "DEADLINE",
      "label": "Price Change Notice Window",
      "rfpQuote": "Requests for price changes must be received in writing at least 30 days prior to their effective date",
      "section": "§20"
    },
    {
      "id": "c15",
      "kind": "DEADLINE",
      "label": "Production Chassis Delivery Deadline",
      "rfpQuote": "Delivery of Production Chassis to the Body Manufacturer should be within 120 days after the Pre-Pilot Model Meeting.",
      "section": "§25"
    },
    {
      "id": "c16",
      "kind": "DEADLINE",
      "label": "Pilot Model Review Meeting Deadline",
      "rfpQuote": "Pilot Model Review Meeting at the manufacturer’s facility, or at a mutually agreed upon location, must be conducted within thirty",
      "section": "§26"
    },
    {
      "id": "c17",
      "kind": "LEGAL",
      "label": "State Data Disposal Restriction",
      "rfpQuote": "Contractor will not dispose of, delete, or destroy State Data without the prior written approval of the State.",
      "section": "§29"
    }
  ],
  "suggestedWeights": [
    {
      "criterionId": "problem_understanding",
      "weight": 1.0,
      "reason": "Standard background information and operational context are requested without unusual domain framing."
    },
    {
      "criterionId": "scope_clarity",
      "weight": 1.4,
      "reason": "The Statement of Work contains granular specifications, pilot model procedures, and inspection protocols that must be clearly addressed."
    },
    {
      "criterionId": "pricing_clarity",
      "weight": 1.3,
      "reason": "Pricing must be firm for 365 days and strictly accounts for pass-through OEM price variations and FTA cost analyses."
    },
    {
      "criterionId": "timeline_clarity",
      "weight": 1.5,
      "reason": "Strict turnaround windows such as 210 business days for delivery, 5-day parts replacement, and 30-day pilot meetings are enforced with liquidated damages."
    },
    {
      "criterionId": "completeness",
      "weight": 1.5,
      "reason": "Extensive checkboxes, background disclosures, environmental standard responses, and worksheet answers must be completely submitted."
    },
    {
      "criterionId": "tone_persuasiveness",
      "weight": 0.7,
      "reason": "This is a compliance-driven public sector vehicle procurement where factual adherence heavily outweighs persuasive pitch tone."
    },
    {
      "criterionId": "risk_transparency",
      "weight": 1.2,
      "reason": "The State demands explicit disclosure of litigation, debarments, defaults, subcontractor roles, and safety/recall mechanisms."
    }
  ]
}
